# Let me compare shapes across ALL regions and normalize them
def normalize_shape(region_mask):
    """
    Given a 5x5 boolean mask of shape pixels, normalize by trimming whitespace
    Returns a canonical representation
    """
    # Remove empty rows
    while region_mask and all(not cell for cell in region_mask[0]):
        region_mask.pop(0)

    # Remove empty cols
    n = len(region_mask[0])
    while n > 0:
        col_has_content = any(cell for row in region_mask for cell in row[n-1])
        if not col_has_content:
            for row in region_mask:
                row.pop()
            n -= 1
        else:
            break

    return tuple(tuple(row) for row in region_mask)

def extract_region_shapes():
    """Extract and normalize all region shapes"""
    shapes = {}
    r_bands = [
        (0, 4), (6, 10), (12, 16), (18, 22), (24, 25)
    ]
    c_bands = [
        (0, 4), (6, 10), (12, 16), (18, 22)
    ]

    for i, (r_start, r_end) in enumerate(r_bands):
        for j, (c_start, c_end) in enumerate(c_bands):
            mask = []
            for r in range(r_start, r_end + 1):
                row = []
                for c in range(c_start, c_end + 1):
                    if input_grid[r][c] != 0 and input_grid[r][c] != 8:
                        row.append(True)
                    else:
                        row.append(False)
                mask.append(tuple(row))

            # Get dominant color
            colors = set()
            for r in range(r_start, r_end + 1):
                for c in range(c_start, c_end + 1):
                    if input_grid[r][c] != 0 and input_grid[r][c] != 8:
                        colors.add(input_grid[r][c])
            color = max(colors) if colors else None

            norm_shape = normalize_shape(mask)
            key = (norm_shape, color)
            shapes[(i,j)] = (norm_shape, color)

    return shapes

